def solve(grid):
    from collections import deque, defaultdict

    h = len(grid)
    w = len(grid[0]) if h else 0

    # Find 4-connected nonzero components
    vis = [[False] * w for _ in range(h)]
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not vis[r][c]:
                color = grid[r][c]
                q = deque([(r, c)])
                vis[r][c] = True
                cells = []
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w and not vis[nx][ny] and grid[nx][ny] == color:
                            vis[nx][ny] = True
                            q.append((nx, ny))

                rs = [x for x, _ in cells]
                cs = [y for _, y in cells]
                r0, r1 = min(rs), max(rs)
                c0, c1 = min(cs), max(cs)
                bh, bw = r1 - r0 + 1, c1 - c0 + 1

                shape = [[0] * bw for _ in range(bh)]
                for x, y in cells:
                    shape[x - r0][y - c0] = color

                comps.append({
                    "color": color,
                    "cells": cells,
                    "size": len(cells),
                    "r0": r0, "r1": r1, "c0": c0, "c1": c1,
                    "h": bh, "w": bw,
                    "shape": shape,
                })

    if not comps:
        return []

    # Heuristic: keep smaller / more specific objects, discard dominant large ones.
    sizes = sorted(c["size"] for c in comps)
    median = sizes[len(sizes) // 2]

    selected = []
    for c in comps:
        bbox_area = c["h"] * c["w"]
        density = c["size"] / bbox_area
        # Prefer components that are relatively small or sparse/non-rectangular
        if c["size"] <= median or density < 0.75 or bbox_area <= 6:
            selected.append(c)

    if not selected:
        selected = comps[:]

    # Merge components of same color if they are all tiny singletons/very small
    by_color = defaultdict(list)
    for c in selected:
        by_color[c["color"]].append(c)

    merged = []
    for color, lst in by_color.items():
        if len(lst) == 1:
            merged.append(lst[0])
        else:
            total_size = sum(x["size"] for x in lst)
            if all(x["size"] <= 2 for x in lst):
                cells = []
                for x in lst:
                    cells.extend(x["cells"])
                rs = [r for r, _ in cells]
                cs = [c for _, c in cells]
                r0, r1 = min(rs), max(rs)
                c0, c1 = min(cs), max(cs)
                bh, bw = r1 - r0 + 1, c1 - c0 + 1
                shape = [[0] * bw for _ in range(bh)]
                for r, c in cells:
                    shape[r - r0][c - c0] = color
                merged.append({
                    "color": color,
                    "cells": cells,
                    "size": total_size,
                    "r0": r0, "r1": r1, "c0": c0, "c1": c1,
                    "h": bh, "w": bw,
                    "shape": shape,
                })
            else:
                merged.extend(lst)

    selected = merged

    # Sort by top-left position
    selected.sort(key=lambda x: (x["r0"], x["c0"]))

    # Group into rows by vertical overlap / proximity
    rows = []
    for comp in selected:
        placed = False
        for row in rows:
            rr0 = min(x["r0"] for x in row)
            rr1 = max(x["r1"] for x in row)
            if not (comp["r0"] > rr1 + 1 or comp["r1"] < rr0 - 1):
                row.append(comp)
                placed = True
                break
        if not placed:
            rows.append([comp])

    # Sort components inside each row
    for row in rows:
        row.sort(key=lambda x: x["c0"])

    # Build output by concatenating component crops with 1-column spacer
    out = []
    for row in rows:
        row_h = max(c["h"] for c in row)
        row_grid = [[0] * 0 for _ in range(row_h)]
        first = True
        for comp in row:
            if not first:
                for rr in range(row_h):
                    row_grid[rr].append(0)
            first = False
            for rr in range(row_h):
                seg = comp["shape"][rr] if rr < comp["h"] else [0] * comp["w"]
                row_grid[rr].extend(seg)
        if out:
            width = max(len(out[0]), len(row_grid[0]) if row_grid else 0)
            for rr in range(len(out)):
                if len(out[rr]) < width:
                    out[rr].extend([0] * (width - len(out[rr])))
            for rr in range(len(row_grid)):
                if len(row_grid[rr]) < width:
                    row_grid[rr].extend([0] * (width - len(row_grid[rr])))
            out.append([0] * width)
        out.extend(row_grid)

    # Trim zero-only rows/cols
    while out and all(v == 0 for v in out[0]):
        out.pop(0)
    while out and all(v == 0 for v in out[-1]):
        out.pop()

    if not out:
        return []

    left = 0
    right = len(out[0]) - 1
    while left <= right and all(row[left] == 0 for row in out):
        left += 1
    while right >= left and all(row[right] == 0 for row in out):
        right -= 1

    return [row[left:right + 1] for row in out]

